 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The colored markers along the top edge each send a vertical ray.
    # If the same color appears elsewhere, turn at that row and extend
    # horizontally to the matching marker; otherwise continue to bottom.
    for c, color in enumerate(grid[0]):
        if color == 0:
            continue
        matches = [(r, x) for r in range(1, h) for x in range(w)
                   if grid[r][x] == color]
        if matches:
            r, x = matches[0]
            for y in range(r + 1):
                out[y][c] = color
            for xx in range(min(c, x), max(c, x) + 1):
                out[r][xx] = color
        else:
            for y in range(h):
                out[y][c] = color
    return out
